ORGANIZER_LEAD_LABELS = ("portal.delete_conference", "portal.start_next_year")
ORGANIZER_MEMBER_LABELS = tuple(
    label for label in CATALOGUE if label not in ORGANIZER_LEAD_LABELS
)


def _permissions(apps, labels):
    ContentType = apps.get_model("contenttypes", "ContentType")
    Permission = apps.get_model("auth", "Permission")
    rows = []
    for label in labels:
        app_label, _, codename = label.partition(".")
        model, name = CATALOGUE[label]
        content_type, _ = ContentType.objects.get_or_create(
            app_label=app_label, model=model
        )
        permission, _ = Permission.objects.get_or_create(
            content_type=content_type, codename=codename, defaults={"name": name}
        )
        rows.append(permission)
    return rows


def seed_organizers_team(apps, schema_editor):
    """An Organizers team for the active edition, from today's staff accounts.

    Every active staff or superuser account gets an approved volunteer
    profile in the edition if it has none, joins the team, and superusers
    lead it (the lead set is the two year-rollover permissions). Safe to run
    again: the team is found by name and memberships are additive.
    """
    Conference = apps.get_model("portal", "Conference")
    active = Conference.objects.filter(is_active=True).first()
    if active is None:
        return
    Team = apps.get_model("volunteer", "Team")
    VolunteerProfile = apps.get_model("volunteer", "VolunteerProfile")
    User = apps.get_model("auth", "User")
    team, _ = Team.objects.get_or_create(
        conference=active,
        short_name=ORGANIZERS,
        defaults={
            "description": "The core team: runs the edition end to end.",
            "open_to_new_members": False,
        },
    )
    team.permissions.set(_permissions(apps, ORGANIZER_MEMBER_LABELS))
    team.lead_permissions.set(_permissions(apps, ORGANIZER_LEAD_LABELS))
    staff = User.objects.filter(Q(is_staff=True) | Q(is_superuser=True), is_active=True)
    for user in staff:
        profile, _ = VolunteerProfile.objects.get_or_create(
            user=user, conference=active, defaults={"application_status": APPROVED}
        )
        if profile.application_status != APPROVED:
            profile.application_status = APPROVED
            profile.save(update_fields=["application_status"])
        profile.teams.add(team)
        if user.is_superuser:
            team.team_leads.add(profile)


ADMIN_ROLES = ("Admin", "Staff")


def roles_to_organizers(apps, schema_editor):
    """Admin and Staff role holders join their edition's Organizers team.

    The team is found by name, or made and given the sets of an existing
    Organizers team (the active edition's, from 0016), so a past edition's
    core team is described the same way as this year's.
    """
    Role = apps.get_model("volunteer", "Role")
    Team = apps.get_model("volunteer", "Team")
    VolunteerProfile = apps.get_model("volunteer", "VolunteerProfile")
    holders = VolunteerProfile.objects.filter(
        roles__in=Role.objects.filter(short_name__in=ADMIN_ROLES)
    ).distinct()
    template = (
        Team.objects.filter(short_name=ORGANIZERS)
        .order_by("-conference__is_active", "-conference__year")
        .first()
    )
    for profile in holders:
        team, created = Team.objects.get_or_create(
            conference_id=profile.conference_id,
            short_name=ORGANIZERS,
            defaults={
                "description": "The core team: runs the edition end to end.",
                "open_to_new_members": False,
            },
        )
        if created and template is not None:
            team.permissions.set(template.permissions.all())
            team.lead_permissions.set(template.lead_permissions.all())
        profile.teams.add(team)


